---@class PlayerInfoUtils
local PlayerInfoUtils = {}


---@param headAvatarId integer
---@return PlayerHeadAvatarVo
function PlayerInfoUtils.GetHeadAvatarVo(headAvatarId)
    return CfUtils.GetCfVo(AutoIds.IdSetting952, "PlayerHeadAvatarVo", headAvatarId)
end


---获取配表中该kind对应的所有道具id
---@param kind Constants.PlayerAvatarItemType @ 种类区分：1头像2头像框3徽章4主题5社团头像6个人信息7性别
---@return string[]
function PlayerInfoUtils.GetItemIdsByKind(kind)
    local SettingPath = AutoIds.IdSetting952
    local IDGroup = string.format("%s%s", SettingPath, "IDGroup")
    local tableFile = SettingMgr:GetInstance():Get(IDGroup)
    local row = tableFile:GetByPrimaryKey(tostring(kind))
    if isNull(row) then
        printError("ret nil")
        return nil
    end
    local ids = string.split(row:Get("ids"), ',')
    PlayerInfoUtils.SortItemIdsByKind(ids, kind)
    return ids
end

---@param kind Constants.PlayerAvatarItemType @ 种类区分：1头像2头像框3徽章4主题5社团头像6个人信息7性别
---@return string[]
function PlayerInfoUtils.SortItemIdsByKind(ids, kind)
    local ownIdMap = PlayerInfoUtils.GetItemHasByKind(kind)
    table.sort(ids, function (a,b)
        if table.haskey(ownIdMap, tostring(a)) and not table.haskey(ownIdMap, tostring(b)) then
            return true
        elseif not table.haskey(ownIdMap, tostring(a)) and table.haskey(ownIdMap, tostring(b)) then
            return false
        else
            local aSort = PlayerInfoUtils.GetHeadAvatarVo(a).sort
            local bSort = PlayerInfoUtils.GetHeadAvatarVo(b).sort
            if aSort ~= bSort then
                return aSort < bSort
            end
        end
    end)
end

