---获取玩家所拥有该kind对应的所有道具信息
---@param kind Constants.PlayerAvatarItemType @ 种类区分：1头像2头像框3徽章4主题5社团头像
---@return table<string, table>
function PlayerInfoUtils.GetItemHasByKind(kind)
    kind = checkString(kind)
    ---@type PlayerComponent
    local playerComponent = GameUtils.GetEntityCompByType(ECSComponentType.Constants.PlayerComponent)
    local dojo = playerComponent.playerDojo.playerOtherInfo
    if next(dojo) == nil then
        local defaultAvatar = PlayerInfoUtils.GetDefaultAvatarId(playerComponent.playerDojo.gender)
        local defaultAvatarFrame = PlayerInfoUtils.GetDefaultAvatarFrameId()
        dojo = {--默认的 头像/头像框/徽章 数据
            [tostring(Constants.PlayerAvatarItemType.Avatar)] = {
                [tostring(defaultAvatar)] = {
                    ["goodsId"] = tostring(defaultAvatar)
                },
                [tostring(playerComponent.playerDojo.playerAvatar)] = {
                    ["goodsId"] = tostring(playerComponent.playerDojo.playerAvatar)
                },
            },
            [tostring(Constants.PlayerAvatarItemType.AvatarFrame)] = {
                [tostring(defaultAvatarFrame)] = {
                    ["goodsId"] = tostring(defaultAvatarFrame)
                },
                [tostring(playerComponent.playerDojo.playerAvatarFrame)] = {
                    ["goodsId"] = tostring(playerComponent.playerDojo.playerAvatarFrame)
                },
            },
            [Constants.PlayerAvatarItemType.Paster] = {
            },
        }
        playerComponent.playerDojo.playerOtherInfo = dojo--设置默认数据
    end
    local data = {}
    if dojo[kind] ~= nil then
        for k, v in pairs(dojo[kind]) do
            data[tostring(v.goodsId)] = v
        end
    end
    return data
end

---从当前list中获取当前id的index(index从0开始)
function PlayerInfoUtils.GetIndex(list, id)
    id = checkString(id)
    for i = 1, #list do
        if tostring(list[i]) == id then
            return i - 1
        end
    end
end

