---是否为当前正在使用的头像或头像框(头像和头像框的id不重复，所以使用同一个方法)
---@param id string
function PlayerInfoUtils.IsCurrentAvatar(id)
    local playerComponent = GameUtils.GetEntityCompByType(ECSComponentType.Constants.PlayerComponent)
    id = checkString(id)
    if id == checkString(playerComponent.playerDojo.playerAvatar) or id == checkString(playerComponent.playerDojo.playerAvatarFrame) then
        return true
    else
        return false
    end
end

function PlayerInfoUtils.GetAvatarNewStateMap()
    ---@type PlayerComponent
    local playerComp = GameUtils.GetOrAddEntityCompByType(ECSComponentType.Constants.PlayerComponent)
    return playerComp:GetAvatarNewInfoMap()
end

function PlayerInfoUtils.UpdateAvatarNewStateById(itemId, isNew)
    local stateMap = PlayerInfoUtils.GetAvatarNewStateMap()
    local itemConf = GoodsConfMgr:GetInstance():GetGoodsVoById(itemId)
    local itemType = tostring(itemConf.kind)

    if not stateMap[itemType] then
        stateMap[itemType] = {}
    end
    if isNew then
        stateMap[itemType][tostring(itemId)] = true
    else
        stateMap[itemType][tostring(itemId)] = nil
    end
    CfUtils.WriteLocalData("playerAvatarNewStateMap", table.serialize(stateMap))
    Events.Broadcast(Constants.EventNames.PlayerUpdateNewState)
end

-- 猜测: 是否有新 头像/头像框/徽章, 如果有新的, 需要在各级显示 "New" 
function PlayerInfoUtils.CheckAvatarIsNew(itemId)
    -- 共有 1,2,3 三个元素, 可能分别代表 头像/头像框/徽章 的新元素的 id
    local stateMap = PlayerInfoUtils.GetAvatarNewStateMap()

    local itemConf = GoodsConfMgr:GetInstance():GetGoodsVoById(itemId)
    local itemType = tostring(itemConf.kind)
    return checkBool(checkTable(stateMap[itemType])[tostring(itemId)]) == true
end


--[[
    推荐使用带参数版, 如: Constants.PlayerAvatarItemType.Avatar
    不带参数版会检测所有类型的, 比如 社团头像 这种 个人信息页面暂时不负责的类型
]]--
function PlayerInfoUtils.CheckAvatarsHasNew(type)
    local stateMap = PlayerInfoUtils.GetAvatarNewStateMap()
    if checkInt(type) <= 0 then
        for _, stateList in pairs(stateMap) do
            if table.count(stateList) > 0 then
                return true
            end
        end
        return false
    else
        return table.count(checkTable(stateMap[tostring(type)])) > 0
    end
end



function PlayerInfoUtils.CheckNewForPlayer2D()
    return  PlayerInfoUtils.CheckAvatarsHasNew(Constants.PlayerAvatarItemType.Avatar) or
            PlayerInfoUtils.CheckAvatarsHasNew(Constants.PlayerAvatarItemType.AvatarFrame) or
            PlayerInfoUtils.CheckAvatarsHasNew(Constants.PlayerAvatarItemType.Paster)
end



