end

function PlayerInfoUtils.CheckIsCDHasNewById(cdId)
    return PlayerInfoUtils.GetCDNewStateMap()[tostring(cdId)] ~= nil
end

function PlayerInfoUtils.UpdateCDNewStateById(cdId, isNew)
    local map = PlayerInfoUtils.GetCDNewStateMap()
    if isNew then
        map[tostring(cdId)] = true
    else
        map[tostring(cdId)] = nil
    end
    CfUtils.WriteLocalData("playerCDNewStateMap", table.serialize(map))
    Events.Broadcast(Constants.EventNames.PlayerCDUpdateNewState)
end

