---@return number @ int
function PlayerInfoUtils.GetGenderId(genderType_)
    if checkInt(genderType_) == checkInt(Constants.PLAYER_GENDER.FEMALE) then 
        return 6270001 -- 62头像头像框道具表
    elseif checkInt(genderType_) == checkInt(Constants.PLAYER_GENDER.MALE) then 
        return 6270002 -- 62头像头像框道具表
    else 
        printError("参数异常 genderType_ = " .. tostring(genderType_) .. "; type = " .. type(genderType_))
        return 6270001
    end 
end 


---@return number @ int
function PlayerInfoUtils.GenderId2Type(genderId_)
    if checkInt(genderId_) == 6270001 then   -- 62头像头像框道具表
        return Constants.PLAYER_GENDER.FEMALE
    elseif checkInt(genderId_) == 6270002 then   -- 62头像头像框道具表
        return Constants.PLAYER_GENDER.MALE
    else 
        printError("参数异常 genderId_ = " .. tostring(genderId_) .. "; type = " .. type(genderId_))
        return Constants.PLAYER_GENDER.FEMALE
    end 
end



return PlayerInfoUtils